export function Compare(less, equal, left, right) {
    const leftNaN = !equal(left, left);
    const rightNaN = !equal(right, right);
    if (leftNaN) {
        return rightNaN ? 0n : -1n;
    }
    if (rightNaN) {
        return 1n;
    }
    if (less(left, right)) {
        return -1n;
    }
    if (less(right, left)) {
        return 1n;
    }
    return 0n;
}
